struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp)
{
    int count = le16_to_cpu(aclp->acl_count);
    struct posix_acl *pacl;
    int i;

    if (count > POSIX_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    pacl = posix_acl_alloc(count, GFP_KERNEL);
    if (!pacl)
        return ERR_PTR(-ENOMEM);

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *e = &aclp->acl_entry[i];
        struct posix_acl_entry *entry = &pacl->a_entries[i];
        int tag = le16_to_cpu(e->e_tag);
        mode_t perm = le16_to_cpu(e->e_perm);

        switch (tag) {
        case XFS_ACL_TAG_USER_OBJ:
            posix_acl_entry_init(entry, ACL_USER_OBJ, perm);
            break;
        case XFS_ACL_TAG_GROUP_OBJ:
            posix_acl_entry_init(entry, ACL_GROUP_OBJ, perm);
            break;
        case XFS_ACL_TAG_OTHER:
            posix_acl_entry_init(entry, ACL_OTHER, perm);
            break;
        case XFS_ACL_TAG_USER:
            posix_acl_entry_init(entry, ACL_USER, perm);
            break;
        case XFS_ACL_TAG_GROUP:
            posix_acl_entry_init(entry, ACL_GROUP, perm);
            break;
        default:
            posix_acl_release(pacl);
            return ERR_PTR(-EINVAL);
        }
    }

    return pacl;
}

struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp) {
    int count = aclp->acl_count;
    struct posix_acl *posix_acl;
    int i;

    if (count > POSIX_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(*posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = count;
    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *posix_entry = &posix_acl->a_entries[i];
        switch (entry->e_tag) {
            case XFS_ACL_USER_OBJ:
                posix_entry->e_tag = POSIX_ACL_USER_OBJ;
                break;
            case XFS_ACL_USER:
                posix_entry->e_tag = POSIX_ACL_USER;
                break;
            case XFS_ACL_GROUP_OBJ:
                posix_entry->e_tag = POSIX_ACL_GROUP_OBJ;
                break;
            case XFS_ACL_GROUP:
                posix_entry->e_tag = POSIX_ACL_GROUP;
                break;
            case XFS_ACL_OTHER:
                posix_entry->e_tag = POSIX_ACL_OTHER;
                break;
            default:
                while (i > 0) {
                    i--;
                    kfree(posix_acl->a_entries[i].e_name);
                }
                kfree(posix_acl);
                return ERR_PTR(-EINVAL);
        }
        posix_entry->e_perm = entry->e_perm;
        if (entry->e_name_size > 0) {
            posix_entry->e_name = kmalloc(entry->e_name_size + 1, GFP_KERNEL);
            if (!posix_entry->e_name) {
                while (i > 0) {
                    i--;
                    kfree(posix_acl->a_entries[i].e_name);
                }
                kfree(posix_acl);
                return ERR_PTR(-ENOMEM);
            }
            memcpy(posix_entry->e_name, entry->e_name, entry->e_name_size);
            posix_entry->e_name[entry->e_name_size] = '\0';
        } else {
            posix_entry->e_name = NULL;
        }
    }
    return posix_acl;
}

